PRAGMA defer_foreign_keys = ON;
CREATE TABLE hnd_sources_next (
 id TEXT PRIMARY KEY, account_id TEXT NOT NULL, number_id TEXT NOT NULL REFERENCES hnd_records(id),
 owner_id TEXT NOT NULL REFERENCES oa_operators(id), owner_version INTEGER NOT NULL, revision INTEGER NOT NULL,
 revoked_at INTEGER, created_at INTEGER NOT NULL,
 UNIQUE(account_id,number_id,revision)
);
INSERT INTO hnd_sources_next SELECT * FROM hnd_sources;
DROP TABLE hnd_sources;
ALTER TABLE hnd_sources_next RENAME TO hnd_sources;
PRAGMA defer_foreign_keys = OFF;

CREATE TABLE hnd_frontdesk_routing (
 id TEXT PRIMARY KEY, line_id TEXT NOT NULL UNIQUE REFERENCES hnd_frontdesk_lines(id),
 line_revision INTEGER NOT NULL, delegation_id TEXT REFERENCES hnd_delegations(id),
 endpoint_kind TEXT, endpoint_destination TEXT, endpoint_revision INTEGER,
 voicemail_url TEXT NOT NULL, max_seconds INTEGER NOT NULL, expires_at INTEGER NOT NULL,
 revision INTEGER NOT NULL, approved_by TEXT NOT NULL, owner_version INTEGER NOT NULL
);
CREATE TABLE hnd_frontdesk_inbound (
 id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES hnd_sources(id), call_sid TEXT NOT NULL,
 line_id TEXT NOT NULL, line_revision INTEGER NOT NULL, route_revision INTEGER,
 branch TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(source_id,call_sid)
);

ALTER TABLE hnd_frontdesk_inbound ADD COLUMN snapshot TEXT NOT NULL DEFAULT '{}';
ALTER TABLE hnd_frontdesk_inbound ADD COLUMN answered_call_sid TEXT;
ALTER TABLE hnd_frontdesk_inbound ADD COLUMN bridge_authorized_at INTEGER;

-- Caller outcomes: owner-set policy versions, one work identity per call, one
-- durable step per receiving system, exact caller charge authorization and
-- owned exceptions. Steps record "sent" before any network effect so a lost
-- response stays uncertain until readback.
CREATE TABLE hnd_rx_policy (
 version INTEGER PRIMARY KEY, body TEXT NOT NULL CHECK(json_valid(body)),
 owner_id TEXT NOT NULL REFERENCES oa_operators(id), owner_version INTEGER NOT NULL, created_at INTEGER NOT NULL
);
CREATE TRIGGER hnd_rx_policy_no_update BEFORE UPDATE ON hnd_rx_policy BEGIN SELECT RAISE(ABORT,'append_only'); END;
CREATE TRIGGER hnd_rx_policy_no_delete BEFORE DELETE ON hnd_rx_policy BEGIN SELECT RAISE(ABORT,'append_only'); END;
CREATE TABLE hnd_rx_outcomes (
 id TEXT PRIMARY KEY, grant_id TEXT NOT NULL REFERENCES hnd_grants(id), case_id TEXT NOT NULL REFERENCES hnd_cases(id),
 call_id TEXT NOT NULL, language TEXT NOT NULL CHECK(language IN ('en','es')), after_hours INTEGER NOT NULL CHECK(after_hours IN (0,1)),
 policy_version INTEGER NOT NULL REFERENCES hnd_rx_policy(version), caller_name TEXT NOT NULL, caller_email TEXT NOT NULL,
 identity_basis TEXT NOT NULL, identity_reported INTEGER NOT NULL CHECK(identity_reported IN (0,1)), payment_method_ref TEXT,
 created_at INTEGER NOT NULL, UNIQUE(grant_id,call_id)
);
CREATE TABLE hnd_rx_steps (
 id TEXT PRIMARY KEY, outcome_id TEXT NOT NULL REFERENCES hnd_rx_outcomes(id),
 kind TEXT NOT NULL CHECK(kind IN ('availability','booking','deposit','crm','support','refund')),
 state TEXT NOT NULL CHECK(state IN ('pending','sent','confirmed','uncertain','rejected','held')),
 request TEXT NOT NULL CHECK(json_valid(request)), request_hash TEXT NOT NULL, external_id TEXT,
 readback TEXT CHECK(readback IS NULL OR json_valid(readback)), attempts INTEGER NOT NULL DEFAULT 0,
 amount_cents INTEGER NOT NULL DEFAULT 0 CHECK(amount_cents>=0), version INTEGER NOT NULL DEFAULT 1,
 created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(outcome_id,kind)
);
CREATE TABLE hnd_rx_authorizations (
 id TEXT PRIMARY KEY, outcome_id TEXT NOT NULL REFERENCES hnd_rx_outcomes(id), amount_cents INTEGER NOT NULL CHECK(amount_cents>0),
 payee TEXT NOT NULL, purpose TEXT NOT NULL, language TEXT NOT NULL, prompt TEXT NOT NULL, prompt_hash TEXT NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('proposed','authorized','declined')), evidence TEXT CHECK(evidence IS NULL OR json_valid(evidence)),
 consumed_by TEXT UNIQUE, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, decided_at INTEGER
);
CREATE TABLE hnd_rx_exceptions (
 id TEXT PRIMARY KEY, outcome_id TEXT NOT NULL REFERENCES hnd_rx_outcomes(id), kind TEXT NOT NULL,
 requested TEXT NOT NULL CHECK(json_valid(requested)), request_hash TEXT NOT NULL, evidence TEXT NOT NULL CHECK(json_valid(evidence)),
 owner_id TEXT NOT NULL REFERENCES oa_operators(id), status TEXT NOT NULL CHECK(status IN ('open','approved','declined','resolved')),
 callback_due_at INTEGER NOT NULL, notification TEXT NOT NULL CHECK(notification IN ('sent','failed','uncertain')),
 decided_by TEXT REFERENCES oa_operators(id), decided_owner_version INTEGER, decided_at INTEGER, note TEXT,
 consumed_by TEXT UNIQUE, created_at INTEGER NOT NULL, UNIQUE(outcome_id,kind,request_hash)
);

-- No dial is created by a recovery proposal. Existing qualified dialer doors
-- retain all list, consent, registry, spend and exact audience requirements.
CREATE TABLE hnd_recovery (
 id TEXT PRIMARY KEY, case_id TEXT NOT NULL UNIQUE REFERENCES hnd_cases(id),
 source_id TEXT NOT NULL REFERENCES hnd_sources(id), call_record_id TEXT NOT NULL REFERENCES hnd_records(id),
 queue_entry_id TEXT REFERENCES hnd_queue_entries(id), queue_place TEXT NOT NULL CHECK(json_valid(queue_place)),
 recipient TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES oa_operators(id), owner_version INTEGER NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('open','human','resolved','declined','stopped','escalated')),
 due_at INTEGER NOT NULL, max_attempts INTEGER NOT NULL CHECK(max_attempts BETWEEN 1 AND 3),
 reason TEXT NOT NULL, resolution TEXT CHECK(resolution IS NULL OR json_valid(resolution)),
 revision INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
);
CREATE TABLE hnd_recovery_events (
 id TEXT PRIMARY KEY, recovery_id TEXT NOT NULL REFERENCES hnd_recovery(id),
 kind TEXT NOT NULL, evidence TEXT NOT NULL CHECK(json_valid(evidence)),
 actor TEXT NOT NULL, created_at INTEGER NOT NULL
);
CREATE TRIGGER hnd_recovery_events_no_update BEFORE UPDATE ON hnd_recovery_events BEGIN SELECT RAISE(ABORT,'append_only'); END;
CREATE TRIGGER hnd_recovery_events_no_delete BEFORE DELETE ON hnd_recovery_events BEGIN SELECT RAISE(ABORT,'append_only'); END;

CREATE TABLE hnd_rule_previews (
 id TEXT PRIMARY KEY, rule_id TEXT NOT NULL, expected_revision INTEGER NOT NULL,
 definition TEXT NOT NULL CHECK(json_valid(definition)), sample_id TEXT NOT NULL REFERENCES hnd_records(id),
 owner_id TEXT NOT NULL, owner_version INTEGER NOT NULL, expires_at INTEGER NOT NULL, used_at INTEGER
);
CREATE TABLE hnd_rules (
 id TEXT PRIMARY KEY, revision INTEGER NOT NULL, definition TEXT NOT NULL CHECK(json_valid(definition)),
 state TEXT NOT NULL CHECK(state IN ('active','paused')), owner_id TEXT NOT NULL, owner_version INTEGER NOT NULL,
 created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
);
CREATE TABLE hnd_rule_versions (
 id TEXT NOT NULL REFERENCES hnd_rules(id), revision INTEGER NOT NULL,
 definition TEXT NOT NULL CHECK(json_valid(definition)), owner_id TEXT NOT NULL, owner_version INTEGER NOT NULL,
 created_at INTEGER NOT NULL, PRIMARY KEY(id,revision)
);
CREATE TABLE hnd_rule_events (
 record_id TEXT PRIMARY KEY REFERENCES hnd_records(id), trigger TEXT NOT NULL,
 created_at INTEGER NOT NULL
);
CREATE TABLE hnd_rule_runs (
 id TEXT PRIMARY KEY, rule_id TEXT NOT NULL REFERENCES hnd_rules(id), rule_revision INTEGER NOT NULL,
 record_id TEXT NOT NULL REFERENCES hnd_records(id), case_id TEXT NOT NULL REFERENCES hnd_cases(id), case_version INTEGER NOT NULL,
 owner_id TEXT NOT NULL, owner_version INTEGER NOT NULL, action TEXT NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('queued','sending','accepted','uncertain','failed','canceled','owned','held')),
 work_status TEXT NOT NULL DEFAULT 'open' CHECK(work_status='open'), due_at INTEGER NOT NULL,
 next_due_at INTEGER NOT NULL, reason TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL,
 UNIQUE(rule_id,record_id), UNIQUE(record_id,action,owner_id)
);
CREATE TRIGGER hnd_rule_versions_no_update BEFORE UPDATE ON hnd_rule_versions BEGIN SELECT RAISE(ABORT,'append_only'); END;
CREATE TRIGGER hnd_rule_versions_no_delete BEFORE DELETE ON hnd_rule_versions BEGIN SELECT RAISE(ABORT,'append_only'); END;

-- Historical outcomes lack a reviewed case snapshot and cannot create new
-- effects. Their existing receipts remain readable. New work pins the case.
ALTER TABLE hnd_rx_outcomes ADD COLUMN case_version INTEGER NOT NULL DEFAULT 0;

CREATE TABLE hnd_operations (
 id TEXT PRIMARY KEY, call_record_id TEXT NOT NULL REFERENCES hnd_records(id), source_id TEXT NOT NULL REFERENCES hnd_sources(id),
 owner_id TEXT NOT NULL REFERENCES oa_operators(id), owner_version INTEGER NOT NULL,
 snapshot TEXT NOT NULL CHECK(json_valid(snapshot)), state TEXT NOT NULL CHECK(state IN ('proposed','approved','declined')),
 decision_note TEXT NOT NULL DEFAULT '', revision INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
);
CREATE TABLE hnd_operations_decisions (
 id TEXT PRIMARY KEY, operation_id TEXT NOT NULL REFERENCES hnd_operations(id),
 decision TEXT NOT NULL, note TEXT NOT NULL, actor_id TEXT NOT NULL, actor_version INTEGER NOT NULL, created_at INTEGER NOT NULL
);

CREATE TABLE hnd_number_compliance (
 id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES hnd_sources(id), number_id TEXT NOT NULL REFERENCES hnd_records(id),
 kind TEXT NOT NULL, reference TEXT NOT NULL, report TEXT NOT NULL CHECK(json_valid(report)),
 owner_id TEXT NOT NULL REFERENCES oa_operators(id), owner_version INTEGER NOT NULL,
 due_at INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('prepared','reviewed','follow_up')),
 plan TEXT NOT NULL, approval_note TEXT NOT NULL DEFAULT '', provider_state TEXT NOT NULL DEFAULT 'unknown',
 readback TEXT CHECK(readback IS NULL OR json_valid(readback)), revision INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL,
 UNIQUE(number_id,kind,reference)
);
CREATE TABLE hnd_number_compliance_events (
 id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES hnd_number_compliance(id), kind TEXT NOT NULL,
 evidence TEXT NOT NULL CHECK(json_valid(evidence)), actor_id TEXT NOT NULL, actor_version INTEGER NOT NULL, created_at INTEGER NOT NULL
);
CREATE TRIGGER hnd_number_compliance_events_no_update BEFORE UPDATE ON hnd_number_compliance_events BEGIN SELECT RAISE(ABORT,'append_only'); END;
CREATE TRIGGER hnd_number_compliance_events_no_delete BEFORE DELETE ON hnd_number_compliance_events BEGIN SELECT RAISE(ABORT,'append_only'); END;

CREATE TABLE hnd_api_idempotency (
 grant_id TEXT NOT NULL REFERENCES hnd_grants(id), key TEXT NOT NULL,
 request_hash TEXT NOT NULL, response TEXT NOT NULL CHECK(json_valid(response)), created_at INTEGER NOT NULL,
 PRIMARY KEY(grant_id,key)
);
CREATE TABLE hnd_api_rate (
 grant_id TEXT NOT NULL REFERENCES hnd_grants(id), window INTEGER NOT NULL, calls INTEGER NOT NULL,
 PRIMARY KEY(grant_id,window)
);

-- Hourly counts of unsigned auth attempts. Only a bounded number of them become
-- audit receipts; the rest are counted here without address, path or payload.
CREATE TABLE hnd_auth_anonymous (
 window INTEGER PRIMARY KEY, attempts INTEGER NOT NULL CHECK(attempts>0)
);

ALTER TABLE hnd_grants ADD COLUMN credential_expires_at INTEGER NOT NULL DEFAULT 0;
ALTER TABLE hnd_grants ADD COLUMN credential_revision INTEGER NOT NULL DEFAULT 1;
UPDATE hnd_grants SET credential_expires_at=expires_at;

CREATE TABLE hnd_authority_scopes (
 id TEXT PRIMARY KEY,
 operator_id TEXT NOT NULL REFERENCES oa_operators(id), operator_version INTEGER NOT NULL,
 definition TEXT NOT NULL CHECK(json_valid(definition)), permissions TEXT NOT NULL CHECK(json_valid(permissions)),
 created_by TEXT NOT NULL REFERENCES oa_operators(id), owner_version INTEGER NOT NULL,
 expires_at INTEGER NOT NULL, revoked_at INTEGER, created_at INTEGER NOT NULL
);
ALTER TABLE hnd_grants ADD COLUMN scope_id TEXT REFERENCES hnd_authority_scopes(id);
ALTER TABLE hnd_approvals ADD COLUMN scope_id TEXT REFERENCES hnd_authority_scopes(id);
ALTER TABLE hnd_standing ADD COLUMN scope_id TEXT REFERENCES hnd_authority_scopes(id);
